PRAGMA foreign_keys = ON;
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings(key,value) VALUES ('origin','https://tt.bz3.eu'),('bot_name','Marius Bot'),('timezone','Europe/Berlin'),('info_text','Trainingsinformationen werden vom Trainer eingerichtet.'),('privacy_text','Die Angaben zum Verantwortlichen werden vor der Freigabe ergänzt.'),('enabled','0'),('privacy_ready','0');
CREATE TABLE users(id TEXT PRIMARY KEY, jid TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL DEFAULT '', registered_at INTEGER, reminders INTEGER NOT NULL DEFAULT 0 CHECK(reminders IN (0,1)), created_at INTEGER NOT NULL);
CREATE TABLE identity_aliases(jid TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE roles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','admin')), created_at INTEGER NOT NULL);
CREATE TABLE groups(jid TEXT PRIMARY KEY, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE memberships(group_jid TEXT NOT NULL REFERENCES groups(jid) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, active INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL, PRIMARY KEY(group_jid,user_id));
CREATE TABLE training_series(id TEXT PRIMARY KEY, group_jid TEXT NOT NULL REFERENCES groups(jid), weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7), start_time TEXT NOT NULL, end_time TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Europe/Berlin', location TEXT NOT NULL, reminder_time TEXT NOT NULL DEFAULT '18:00', late_offset INTEGER NOT NULL DEFAULT 30 CHECK(late_offset BETWEEN 0 AND 240), active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE training_exceptions(id TEXT PRIMARY KEY, series_id TEXT NOT NULL REFERENCES training_series(id), from_date TEXT NOT NULL, to_date TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('cancel','pause')), created_at INTEGER NOT NULL);
CREATE TABLE training_sessions(id TEXT PRIMARY KEY, series_id TEXT REFERENCES training_series(id), group_jid TEXT NOT NULL REFERENCES groups(jid), local_date TEXT NOT NULL, start_at INTEGER NOT NULL, end_at INTEGER NOT NULL, timezone TEXT NOT NULL, location TEXT NOT NULL, invite_at INTEGER NOT NULL, late_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','cancelled')), version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, UNIQUE(series_id,local_date));
CREATE INDEX sessions_upcoming ON training_sessions(start_at,status);
CREATE TABLE attendance(session_id TEXT NOT NULL REFERENCES training_sessions(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, response TEXT NOT NULL DEFAULT 'unknown', punctuality TEXT NOT NULL DEFAULT 'unknown', minutes INTEGER, arrival_time TEXT, response_source TEXT, response_at INTEGER NOT NULL DEFAULT 0, late_source TEXT, late_updated_at INTEGER NOT NULL DEFAULT 0, needs_confirmation INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, PRIMARY KEY(session_id,user_id));
CREATE TABLE messages(id TEXT PRIMARY KEY, chat_jid TEXT NOT NULL, session_id TEXT REFERENCES training_sessions(id) ON DELETE CASCADE, session_version INTEGER, kind TEXT NOT NULL, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, UNIQUE(chat_jid,id));
CREATE TABLE inbox_events(id TEXT PRIMARY KEY, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease_until INTEGER, error TEXT);
CREATE INDEX inbox_pending ON inbox_events(status,created_at);
CREATE TABLE outbox_jobs(id TEXT PRIMARY KEY, dedupe_key TEXT NOT NULL UNIQUE, chat_jid TEXT NOT NULL, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, session_id TEXT REFERENCES training_sessions(id) ON DELETE CASCADE, session_version INTEGER, kind TEXT NOT NULL, text TEXT NOT NULL, due_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, lease_until INTEGER, provider_id TEXT, error TEXT, created_at INTEGER NOT NULL);
CREATE INDEX outbox_due ON outbox_jobs(status,due_at);
CREATE TABLE conversations(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, data TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE consents(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL, version TEXT NOT NULL, accepted INTEGER NOT NULL CHECK(accepted IN(0,1)), event_id TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE audit_log(id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, detail TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
